dependencies {
    compileOnly("io.papermc.paper:paper-api:${property("paperVersion")}")
    compileOnly("org.geysermc.floodgate:api:${property("floodgateVersion")}")
    compileOnly("org.geysermc.geyser:api:${property("geyserVersion")}")
}

// Example images (poster + animated GIF) generated by tools/generate_examples.py, installed on first start
val examplesZip = tasks.register<Zip>("examplesZip") {
    from("src/main/examples")
    archiveFileName.set("examples.zip")
    destinationDirectory.set(layout.buildDirectory.dir("generated/examples"))
    isPreserveFileTimestamps = false
    isReproducibleFileOrder = true
}

tasks.processResources {
    val props = mapOf("version" to project.version)
    inputs.properties(props)
    filesMatching("plugin.yml") { expand(props) }
    from(examplesZip)
}

tasks.jar {
    archiveBaseName.set("SimplexImageToMap")
    archiveClassifier.set("")
}
